def process(mmc1) -> pd.DataFrame:
    import pandas as pd

    df = mmc1.copy()

    # Keep only tumor samples that are part of the study
    # (exclude cases flagged as excluded)
    col_excl = 'Case_excluded'
    col_tn = 'Proteomics_Tumor_Normal'

    # Normalize strings
    for c in [col_excl, col_tn, 'idx']:
        if c in df.columns:
            df[c] = df[c].astype(str).str.strip()

    tumor = df[df[col_tn].str.upper().eq('TUMOR')]
    in_study = tumor[~tumor[col_excl].str.upper().eq('YES')]

    # Map Sxxx -> participant id (C3L-xxxxx)
    out = in_study[['idx', 'Proteomics_Participant_ID']].rename(
        columns={'idx': 'sampleId', 'Proteomics_Participant_ID': 'participantId'}
    )

    return out.dropna(subset=['sampleId']).drop_duplicates()

def process(plk1Tumor, chek2S163Tumor) -> pd.DataFrame:
    import pandas as pd

    a = plk1Tumor.copy()
    b = chek2S163Tumor.copy()

    if 'error' in a.columns:
        return a
    if 'error' in b.columns:
        return b

    merged = a.merge(b, on='sampleId', how='inner')
    merged['plk1'] = pd.to_numeric(merged['plk1'], errors='coerce')
    merged['chek2S163'] = pd.to_numeric(merged['chek2S163'], errors='coerce')

    clean = merged.dropna(subset=['plk1', 'chek2S163'])
    if clean.shape[0] < 2:
        return pd.DataFrame({'spearman': [float('nan')], 'n': [clean.shape[0]]})

    rho = clean['plk1'].corr(clean['chek2S163'], method='spearman')
    return pd.DataFrame({'spearman': [rho], 'n': [clean.shape[0]]})
